import React from 'react';
import { useTranslation } from 'react-i18next';
import { NavLink } from 'react-router-dom';
import { useAppShellStore } from '../../stores/appShellStore';
import './AdminSidebar.css';

const navClass = ({ isActive }: { isActive: boolean }): string =>
  `admin-sidebar__link${isActive ? ' admin-sidebar__link--active' : ''}`;

function AdminSidebar(): React.ReactElement {
  const { t } = useTranslation('common');
  const collapsed = useAppShellStore((s) => s.sidebarCollapsed);
  const mobileOpen = useAppShellStore((s) => s.mobileSidebarOpen);
  const toggleCollapsed = useAppShellStore((s) => s.toggleSidebarCollapsed);
  const setMobileOpen = useAppShellStore((s) => s.setMobileSidebarOpen);

  return (
    <aside
      className={`admin-sidebar${collapsed ? ' admin-sidebar--collapsed' : ''}${mobileOpen ? ' admin-sidebar--open' : ''}`}
      aria-label={t('shell.mainNavAria')}
    >
      <div className="admin-sidebar__toolbar">
        <button
          type="button"
          className="admin-sidebar__icon-btn"
          onClick={toggleCollapsed}
          aria-pressed={collapsed}
          aria-label={collapsed ? t('shell.expandSidebar') : t('shell.collapseSidebar')}
        >
          {collapsed ? '»' : '«'}
        </button>
        <button
          type="button"
          className="admin-sidebar__icon-btn admin-sidebar__icon-btn--mobile"
          onClick={() => setMobileOpen(false)}
          aria-label={t('shell.closeMenu')}
        >
          ✕
        </button>
      </div>

      <div className="admin-sidebar__brand">
        <span className="admin-sidebar__brand-title">DBMercado</span>
        <span className="admin-sidebar__brand-sub">{t('app.admin')}</span>
      </div>

      <nav className="admin-sidebar__nav">
        <div className="admin-sidebar__section-label">{t('nav.sectionMain')}</div>
        <NavLink
          to="/admin/dashboard"
          className={navClass}
          end
          onClick={() => setMobileOpen(false)}
        >
          {t('nav.dashboard')}
        </NavLink>

        <div className="admin-sidebar__section-label">{t('nav.sectionGov')}</div>
        <NavLink to="/admin/users" className={navClass} onClick={() => setMobileOpen(false)}>
          {t('nav.users')}
        </NavLink>
        <NavLink to="/admin/roles" className={navClass} onClick={() => setMobileOpen(false)}>
          {t('nav.roles')}
        </NavLink>
        <NavLink to="/admin/audit" className={navClass} onClick={() => setMobileOpen(false)}>
          {t('nav.audit')}
        </NavLink>

        <div className="admin-sidebar__section-label">{t('nav.sectionOps')}</div>
        <NavLink to="/admin/products" className={navClass} onClick={() => setMobileOpen(false)}>
          {t('nav.products')}
        </NavLink>
        <NavLink to="/admin/orders" className={navClass} onClick={() => setMobileOpen(false)}>
          {t('nav.orders')}
        </NavLink>
        <NavLink to="/admin/inventory" className={navClass} onClick={() => setMobileOpen(false)}>
          {t('nav.inventory')}
        </NavLink>
        <NavLink to="/admin/billing" className={navClass} onClick={() => setMobileOpen(false)}>
          {t('nav.billing')}
        </NavLink>
      </nav>
    </aside>
  );
}

export default AdminSidebar;
